// La dirección del CRM, de la tabla configuracion
const config = Object.fromEntries($input.all().map((i) => [i.json.clave, i.json.valor]));
if (!config.crm_url) throw new Error('Falta la fila crm_url en la tabla configuracion');
return [{ json: { crm_url: config.crm_url.replace(/\/$/, '') } }];

// Los correos que armó el CRM, uno por persona. Si no hay, sigue un ítem vacío para llegar a las alarmas
const r = $('Tomar resúmenes').first().json;
if (r.error || !Array.isArray(r.correos)) return [{ json: {} }];
if (!r.correos.length) return [{ json: {} }];
return r.correos.map((c) => ({ json: { ref: c.id, para: c.para, quien: c.quien, asunto: c.asunto, texto: c.texto } }));

// Por cada resumen: si el correo salió se confirma (y el CRM anota qué se avisó); si falló, se suelta
// para que la hora siguiente lo intente otra vez
const correos = $('Correos del CRM').all().map((i) => i.json);
const resultados = $input.all().map((i) => i.json);
// Si el subflujo 00b falló entero (por ejemplo, faltan filas en destinos_prueba), no salió ningún correo:
// se sueltan todos
if (resultados.some((r) => !('ok' in r))) {
  const motivo = resultados.find((r) => r.error)?.error;
  return correos.map((c) => ({ json: { resumen: c.ref, quien: c.quien, accion: 'soltar', error: motivo?.message ?? motivo ?? 'falló el envío' } }));
}
const quien = Object.fromEntries(correos.map((c) => [c.ref, c.quien]));
return resultados.map((e) => ({
  json: { resumen: e.ref, quien: quien[e.ref] ?? '', accion: e.ok ? 'confirmar' : 'soltar', error: e.error },
}));

// Las alarmas de esta vuelta. Antes de las 12 m. nada suena: la hora siguiente lo intenta otra vez.
// Desde las 12 m., una sola alarma al día (sin nombres de clientes, solo quién no recibió su resumen)
const problemas = [];

// n8n reescribe los mensajes con códigos de red (ECONNREFUSED...): se traducen antes (como en 01d)
const traducir = (m) =>
  /ECONNREFUSED|ECONNRESET/.test(m) ? 'el CRM no contesta: está apagado o sin conexión'
  : /ETIMEDOUT|ESOCKETTIMEDOUT|timeout/i.test(m) ? 'tardó demasiado en contestar'
  : /ENOTFOUND|EAI_AGAIN/.test(m) ? 'no se encontró la dirección'
  : /401|authoriz/i.test(m) ? 'la llave no coincide (AUTOMATIZACIONES_TOKEN en n8n y en el CRM)'
  : m.slice(0, 150);
const tomar = $('Tomar resúmenes').first().json;
if (tomar.error || !Array.isArray(tomar.correos)) {
  problemas.push(`no se pudieron pedir los resúmenes al CRM (${traducir(String(tomar.error?.message ?? tomar.error ?? 'respuesta inesperada'))})`);
}
if ($('Decidir').isExecuted) {
  const soltados = $('Decidir').all().filter((i) => i.json.accion === 'soltar');
  if (soltados.length) problemas.push(`no salió el correo de ${soltados.map((i) => i.json.quien).join(', ')} (${traducir(String(soltados[0].json.error ?? ''))})`);
}
if (tomar.sin_gerente) {
  problemas.push('no hay una gerente activa en el CRM: los avisos de 7+ días y lo de los asesores inactivos no tienen a quién llegar');
}
if ($('Anotar en el CRM').isExecuted) {
  // Cada respuesta del CRM con lo que se le pidió (mismo orden): un error, o un "no" (otra ejecución
  // retomó la reserva porque esta tardó más de 30 minutos)
  const anotar = $('Anotar en el CRM').all().map((item, i) => ({ r: item.json, pedido: $('Decidir').itemMatching(i).json }));
  const sinConfirmar = anotar.filter(({ r, pedido }) => pedido.accion === 'confirmar' && (r.error || r.confirmado !== true));
  const sinSoltar = anotar.filter(({ r, pedido }) => pedido.accion === 'soltar' && r.error);
  if (sinConfirmar.length) problemas.push(`${sinConfirmar.length} resumen(es) salieron pero el CRM no los anotó: pueden llegar repetidos`);
  if (sinSoltar.length) problemas.push(`${sinSoltar.length} resumen(es) que fallaron no se pudieron soltar: se reintentan en 30 minutos`);
}

const memoria = $getWorkflowStaticData('global');
const hoy = $now.toFormat('yyyy-MM-dd');
let alarma = null;
if (problemas.length && $now.hour >= 12 && memoria.ultimaAlarma !== hoy) {
  memoria.ultimaAlarma = hoy;
  alarma = `Seguimiento de ventas: ${problemas.join('; ')}. Se reintenta cada hora hasta las 6 p. m.`;
}
return [{ json: { alarma } }];
